<?= view('store/partials/header',['title'=>'سبد خرید | گره']) ?><main class="container"><h1>سبد خرید</h1><?php if(session()->getFlashdata('cart_error')): ?><p role="alert"><?= esc(session()->getFlashdata('cart_error')) ?></p><?php endif; ?><?php if(session()->getFlashdata('cart_success')): ?><p role="status"><?= esc(session()->getFlashdata('cart_success')) ?></p><?php endif; ?><?php if(!$lines): ?><div class="empty">سبد خرید شما خالی است. <a href="<?= site_url('shop') ?>">مشاهده فروشگاه</a></div><?php else: ?><?php foreach($lines as $line): ?><article class="product-details-section"><h2><a href="<?= site_url('product/'.rawurlencode($line['product']['slug'])) ?>"><?= esc($line['product']['name']) ?></a></h2><p class="muted"><?= esc($line['variant']['color_name']??'') ?> / <?= esc($line['variant']['size_label']??'') ?></p><p><?= number_format($line['price']) ?> تومان</p><form action="<?= site_url('cart/update') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="variant_id" value="<?= (int)$line['variant']['id'] ?>"><label>تعداد <input type="number" name="quantity" min="0" max="<?= $line['available'] ?>" value="<?= $line['quantity'] ?>" style="width:75px"></label><button class="pill" type="submit">به‌روزرسانی</button></form><p>جمع: <?= number_format($line['subtotal']) ?> تومان</p></article><?php endforeach; ?><section class="product-details-section"><h2>جمع کل: <?= number_format($total) ?> تومان</h2><p class="muted">ثبت سفارش و پرداخت آنلاین پس از اتصال سرویس‌های مشتری و پرداخت فعال می‌شود.</p><button class="pill" disabled>ادامه فرایند خرید</button></section><?php endif; ?></main><?= view('store/partials/footer') ?>